// Aparência, galeria de retratos e seletores temáticos.
let uploadedPortraits=[];let portraitStore=null;
const isPortraitData=s=>typeof s==='string'&&s.length<400000&&/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(s);
function ensurePortraits(){let next=0;for(const x of db.chars){if(!Number.isInteger(x.portraitKey)||x.portraitKey<0)x.portraitKey=next%12;x.portraitKey%=12;next++;if(x.portraitUpload&&!isPortraitData(x.portraitUpload.data))delete x.portraitUpload;}}
function originalArtStyle(index){return `background-position:${index%4*100/3}% ${Math.floor(index/4)*50}%`;}
function renderPortrait(){const band=document.querySelector('#portrait-band'),x=c();band.hidden=!x;if(!x){band.innerHTML='';return;}const art=x.portraitUpload?`<img class="portrait-upload-image" src="${x.portraitUpload.data}" alt="Retrato de ${esc(x.name)}">`:`<div class="portrait-art" role="img" aria-label="Retrato de ${esc(x.name)}" style="${originalArtStyle(x.portraitKey)}"></div>`;band.innerHTML=`<div class="portrait-identity"><button class="portrait-frame portrait-edit-target" aria-label="Editar personagem" title="Editar personagem" onclick="openIdentity()">${art}</button></div><button class="header-dice-roller" aria-label="Abrir rolador de dados" title="Rolador de Dados" onclick="openDiceRoller()"><svg viewBox="0 0 54 58" aria-hidden="true"><path d="M27 3 49 16 46 43 27 55 8 43 5 16Z M27 3 15 23 39 23 27 44 15 23 8 43 27 44 46 43 39 23 49 16 M5 16 15 23 M27 44 27 55 M27 3 39 23"/></svg></button><div class="portrait-evolve-area"><button class="primary portrait-evolve" onclick="openLevelUp()">EVOLUIR</button></div>`;const cls=x.classes?.[0]?.name||x.cls,ci=CLASSES.indexOf(cls),hero=document.querySelector('.hero');if(ci>=0){hero.style.backgroundImage=`linear-gradient(90deg,#102331bf,#10233138 48%,#10233115),url('class-scene-${ci}.webp')`;hero.style.backgroundSize='100% 100%,cover';hero.style.backgroundPosition='center,68% 35%';hero.setAttribute('data-class',cls);}else{hero.style.backgroundImage='';hero.style.backgroundSize='';hero.style.backgroundPosition='';}if(band.parentElement!==hero)hero.appendChild(band);}
function allUploadedPortraits(){const all=new Map(uploadedPortraits.map(p=>[p.id,p]));for(const x of db.chars)if(x.portraitUpload&&isPortraitData(x.portraitUpload.data))all.set(x.portraitUpload.id,x.portraitUpload);return [...all.values()];}
function openPortraitGallery(){if(!c())return;renderGallery();document.querySelector('#portrait-gallery').showModal();}
function renderGallery(){const x=c(),box=document.querySelector('#portrait-options');if(!x)return;const names=['Paladino humano','Maga élfica','Guerreiro anão','Barda tiefling','Patrulheiro orc','Druida humana','Cavaleiro draconato','Monja humana','Artífice gnomo','Clériga aasimar','Ladino élfico','Bárbara goliath'];box.innerHTML=names.map((name,i)=>`<button class="portrait-choice" aria-label="${name}" aria-pressed="${!x.portraitUpload&&x.portraitKey===i}" onclick="selectOriginalPortrait(${i})"><span class="gallery-thumb portrait-art" style="${originalArtStyle(i)}"></span><span>${name}</span></button>`).join('');const uploads=allUploadedPortraits();document.querySelector('#portrait-upload-options').innerHTML=uploads.length?uploads.map((p,i)=>`<button class="portrait-choice" aria-label="${esc(p.name)}" aria-pressed="${x.portraitUpload?.id===p.id}" onclick="selectUploadedPortrait(${i})"><img class="gallery-thumb" src="${p.data}" alt=""><span>${esc(p.name)}</span></button>`).join(''):'<p class="muted">As imagens que você enviar aparecerão aqui.</p>';}
function selectOriginalPortrait(i){if(!c()||!Number.isInteger(i)||i<0||i>11)return;c().portraitKey=i;delete c().portraitUpload;save();document.querySelector('#portrait-gallery').close();render();}
function selectUploadedPortrait(i){const p=allUploadedPortraits()[i];if(!p||!c())return;c().portraitUpload={...p};save();document.querySelector('#portrait-gallery').close();render();}
async function storePortrait(p){if(!portraitStore)throw Error('Armazenamento indisponível');return new Promise((resolve,reject)=>{const tx=portraitStore.transaction('images','readwrite');tx.objectStore('images').put(p);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
function loadPortraitStore(){return new Promise(resolve=>{if(!window.indexedDB){resolve();return;}const req=indexedDB.open('codice-portrait-gallery',1);req.onupgradeneeded=()=>req.result.createObjectStore('images',{keyPath:'id'});req.onsuccess=()=>{portraitStore=req.result;const tx=portraitStore.transaction('images','readonly'),get=tx.objectStore('images').getAll();get.onsuccess=()=>{uploadedPortraits=get.result.filter(p=>isPortraitData(p.data));resolve();};get.onerror=()=>resolve();};req.onerror=()=>resolve();});}
async function uploadPortrait(event){const file=event.target.files?.[0];event.target.value='';if(!file||!c())return;const charId=c().id,status=document.querySelector('#portrait-upload-status');status.textContent='Preparando imagem…';try{if(!file.type.startsWith('image/')||file.size>20000000)throw Error('Escolha uma imagem de até 20 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const img=await new Promise((resolve,reject)=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(Error('Não foi possível abrir a imagem. Use JPG, PNG ou WebP.'));el.src=data;});const canvas=document.createElement('canvas');canvas.width=canvas.height=384;const side=Math.min(img.naturalWidth,img.naturalHeight);canvas.getContext('2d').drawImage(img,(img.naturalWidth-side)/2,(img.naturalHeight-side)/2,side,side,0,0,384,384);const p={id:crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,'').slice(0,60)||'Meu retrato',data:canvas.toDataURL('image/jpeg',.85)};if(!isPortraitData(p.data))throw Error('Imagem muito grande.');await storePortrait(p);uploadedPortraits.push(p);const char=db.chars.find(x=>x.id===charId);if(char)char.portraitUpload={...p};save();render();renderGallery();status.textContent='Imagem salva e aplicada. Ela também está na galeria.';}catch(e){status.textContent=e.message||'Não foi possível salvar a imagem.';}}
let activeChoiceSelect=null;
function enhanceSelects(root=document){root.querySelectorAll('select').forEach(select=>{let button=select.nextElementSibling;if(!button?.classList.contains('fantasy-select')){button=document.createElement('button');button.type='button';button.className='fantasy-select';button.setAttribute('aria-haspopup','dialog');select.insertAdjacentElement('afterend',button);select.classList.add('native-select-hidden');button.onclick=()=>openChoiceDialog(select);}button.disabled=select.disabled;button.textContent=select.options[select.selectedIndex]?.textContent||'Escolher';button.setAttribute('aria-label',select.getAttribute('aria-label')||'Escolher opção');});}
function openChoiceDialog(select){activeChoiceSelect=select;const label=select.getAttribute('aria-label')||select.closest('label')?.firstChild?.textContent?.trim()||'Escolher opção';document.querySelector('#choice-title').textContent=label;document.querySelector('#choice-search').value='';renderChoices('');document.querySelector('#choice-dialog').showModal();}
function renderChoices(term){const select=activeChoiceSelect;if(!select)return;const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();term=normalize(term);document.querySelector('#choice-options').innerHTML=Array.from(select.options).map((option,i)=>({option,i})).filter(({option})=>normalize(option.textContent).includes(term)).map(({option,i})=>`<button type="button" class="choice-option" role="option" aria-selected="${i===select.selectedIndex}" ${option.disabled?'disabled':''} onclick="chooseOption(${i})"><span class="choice-symbol" aria-hidden="true">${i===select.selectedIndex?'◆':'◇'}</span><span>${esc(option.textContent)}</span><span class="choice-check" aria-hidden="true">${i===select.selectedIndex?'✓':''}</span></button>`).join('')||'<p class="muted">Nenhuma opção encontrada.</p>';}
function chooseOption(i){const select=activeChoiceSelect;if(!select||!select.options[i]||select.options[i].disabled)return;document.querySelector('#choice-dialog').close();activeChoiceSelect=null;select.selectedIndex=i;select.dispatchEvent(new Event('change',{bubbles:true}));enhanceSelects();}
const renderBeforeFantasy=render;render=function(){ensurePortraits();renderBeforeFantasy();renderPortrait();const level=c()?.level;document.querySelector('#levelBadge').textContent=level?'NÍVEL':'AVENTURA';document.querySelector('#crest-number').textContent=level??'—';document.querySelector('.seal').setAttribute('aria-label',level?'Nível '+level:'Nenhum personagem selecionado');document.querySelectorAll('#view>.card, #view>.grid>.card').forEach((card,i)=>{if(i%3===0){let mark=document.createElement('img');mark.src='sigil.svg';mark.alt='';mark.className='arcane-mark';mark.setAttribute('aria-hidden','true');card.appendChild(mark);}});enhanceSelects();};
const createBeforeFantasy=create;create=function(){createBeforeFantasy();enhanceSelects(document.querySelector('#modal'));};
render();loadPortraitStore().then(()=>{if(document.querySelector('#portrait-gallery').open)renderGallery();});
